-- metric_id: ub.completed_worker_bands
-- bindings: []
SELECT e."worker_band",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT * FROM (SELECT p."assignment_id",p."pekerja_laki_laki",p."pekerja_perempuan",p."jumlah_pekerja",p."memiliki_catatan_keuangan",p."total_pendapatan",p."total_pengeluaran",p."total_aset",p."__key_valid",p."__conflict",WORKER_BAND(p.pekerja_laki_laki,p.pekerja_perempuan,p.jumlah_pekerja,NULL) AS worker_band FROM mart_ub_b p WHERE p.__key_valid=1 AND p.__conflict=0 AND EXISTS (SELECT 1 FROM mart_ub_a u WHERE u.assignment_id=p.assignment_id AND u.status_keberadaan='1. Ditemukan dan masih aktif') AND EXISTS (SELECT 1 FROM mart_assignment_ub a WHERE a.assignment_id=p.assignment_id AND a.status_assignment IN ('APPROVED BY Pengawas','COMPLETED BY Admin Kabupaten'))) LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."worker_band";

-- metric_id: ub.kategori_distribution
-- bindings: []
SELECT e."kategori_kbli",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "assignment_id","status_keberadaan","kbli_akhir","kategori_kbli","has_assignment_ub","has_ub_a","has_ub_b","has_ub_c" FROM "mart_ub_integrated" LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."kategori_kbli";

-- metric_id: ub.kbli_distribution
-- bindings: []
SELECT e."kbli_akhir",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "assignment_id","status_keberadaan","kbli_akhir","kategori_kbli","has_assignment_ub","has_ub_a","has_ub_b","has_ub_c" FROM "mart_ub_integrated" LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."kbli_akhir";

-- metric_id: usaha.completed_worker_bands
-- bindings: []
SELECT e."worker_band",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT * FROM (SELECT p."assignment_id",p."__version_normalized",p."index1",p."pekerja_laki_laki",p."pekerja_perempuan",p."total_pekerja_jenis_kelamin",p."status_konsistensi_pekerja",p."__key_valid",p."__conflict",WORKER_BAND(p.pekerja_laki_laki,p.pekerja_perempuan,p.total_pekerja_jenis_kelamin,COALESCE(p.status_konsistensi_pekerja,'UNVERIFIED')) AS worker_band FROM mart_program_usaha p WHERE p.__key_valid=1 AND p.__conflict=0 AND EXISTS (SELECT 1 FROM mart_usaha u WHERE u.assignment_id=p.assignment_id AND u.__version_normalized=p.__version_normalized AND u.index1=p.index1 AND u.kode_keberadaan_usaha IN ('1','2')) AND EXISTS (SELECT 1 FROM mart_assignment_tgr a WHERE a.assignment_id=p.assignment_id AND a.status_assignment IN ('APPROVED BY Pengawas','COMPLETED BY Admin Kabupaten'))) LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."worker_band";

-- metric_id: usaha.kategori_distribution
-- bindings: []
SELECT e."kategori",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","index1","kode_keberadaan_usaha","kbli","kategori" FROM "mart_usaha" LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."kategori";

-- metric_id: usaha.kbli_coverage
-- bindings: []
SELECT COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND KBLI_VALID(e."kbli")=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","index1","kode_keberadaan_usaha","kbli","kategori" FROM "mart_usaha" LIMIT -1 OFFSET 0) e WHERE 1=1;

-- metric_id: usaha.kbli_distribution
-- bindings: []
SELECT e."kbli",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","index1","kode_keberadaan_usaha","kbli","kategori" FROM "mart_usaha" LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."kbli";
